// ============================================================
// Dedup + Route: RabbitMQ -> Telegram
// - Static data ($getWorkflowStaticData) hanya persist SETELAH workflow diaktifkan.
//   Saat test mode (Execute Workflow), static data TIDAK disimpan -> bisa dobel 1x.
// - Batasi store 500 deliveryId terakhir.
// ============================================================

const ADMIN_CHAT_ID = 'REPLACE_WITH_ADMIN_GROUP_CHAT_ID';
const store = $getWorkflowStaticData('global');
store.seen = store.seen || {};

const esc = (s) => String(s ?? '').replace(/&/g, '&').replace(/</g, '<').replace(/>/g, '>').replace(/"/g, '"');
const out = [];

for (const item of $input.all()) {
  const m = item.json;

  // Validasi payload minimal
  if (!m || !m.deliveryId || !m.event) continue;
  if (store.seen[m.deliveryId]) continue;
  store.seen[m.deliveryId] = Date.now();

  // Batasi ukuran static data (simpan 500 deliveryId terakhir)
  const keys = Object.keys(store.seen);
  if (keys.length > 500) {
    for (const k of keys.slice(0, keys.length - 500)) delete store.seen[k];
  }

  const d = m.data || {};
  let chatId = null;
  let text = null;
  let fallbackNote = '';

  if (m.event === 'user.invited') {
    // DM invitee; bila tidak ada telegram -> fallback grup admin
    chatId = (d.telegram && d.telegram.telegramId) || ADMIN_CHAT_ID;
    if (!(d.telegram && d.telegram.telegramId)) {
      fallbackNote = '<br/><i>(target DM tidak ada &mdash; diteruskan ke grup admin)</i>';
    }
    text = '<b>Undangan Akses</b><br/>' +
      'Halo ' + esc(d.user && d.user.name) + ',<br/>' +
      'Akun <b>' + esc(d.user && d.user.email) + '</b> (role: ' + esc(d.user && d.user.role) + ') telah dibuat.<br/>' +
      'Silakan login di aplikasi After-Sales.' + fallbackNote;
  } else if (m.event === 'ticket.claimed') {
    // Grup client/location tiket; bila tidak ada -> fallback grup admin
    chatId = (d.group && d.group.chatId) || ADMIN_CHAT_ID;
    if (!(d.group && d.group.chatId)) {
      fallbackNote = '<br/><i>(grup tiket tidak ditemukan &mdash; fallback grup admin)</i>';
    }
    text = '<b>Tiket diklaim</b><br/>' +
      'Tiket <code>' + esc(d.ticketId) + '</code> diklaim oleh <b>' + esc(d.claimer && d.claimer.name) + '</b>.' + fallbackNote;
  } else if (m.event === 'ticket.member_added') {
    // DM ke anggota baru saja; tanpa telegram -> TANPA pesan grup (skip)
    chatId = d.addedMember && d.addedMember.telegram && d.addedMember.telegram.telegramId;
    if (chatId) {
      text = '<b>Kamu ditambahkan ke tiket</b><br/>' +
        'Tiket <code>' + esc(d.ticketId) + '</code> &mdash; ditambahkan oleh <b>' + esc(d.addedBy) + '</b>.';
    }
  } else if (m.event === 'otp.password_reset') {
    chatId = d.telegram && d.telegram.telegramId;
    if (chatId) {
      text = '<b>Reset Password</b><br/>' +
        'OTP kamu: <code>' + esc(d.otp) + '</code><br/>' +
        'Berlaku ' + esc(d.expiresInMinutes) + ' menit. Jangan bagikan ke siapa pun.';
    }
  }

  if (chatId && text) out.push({ json: Object.assign({}, m, { _chatId: chatId, _text: text }) });
}

return out;
